/bin/bash -c "python3 - <<'PY'
# Apply Algorithm 1's role attachment to two FAC events sharing one span.
gold = {('trigger_1', 'shared_span', 'Subject'), ('trigger_2', 'shared_span', 'Object')}
mention_roles = {role for _, _, role in gold}
eals = {(trigger, span) for trigger, span, _ in gold}
fac_roles = {'Subject', 'Object', 'Target', 'Condition', 'Reason', 'Dataset', 'Extent'}
decoded = {(trigger, span, role) for trigger, span in eals for role in mention_roles if role in fac_roles}
print('Gold relations:', sorted(gold))
print('Decoded relations:', sorted(decoded))
print('Additional relations:', sorted(decoded - gold))
PY"
